use bhoo::android_dialer_filter::{DialerFilterState,DialerMode};
#[test] fn letters_hide_digits_and_deleting_restores_both(){let mut s=DialerFilterState::default();s.type_char('2');assert_eq!(s.digits(),"2");assert_eq!(s.letters(),"2");s.type_char('a');assert_eq!(s.mode,DialerMode::DigitsAndLettersNoDigits);assert_eq!(s.digits(),"");assert_eq!(s.letters(),"2A");s.backspace();assert_eq!(s.mode,DialerMode::DigitsAndLetters);assert_eq!(s.digits(),"2");assert_eq!(s.letters(),"2");}
#[test] fn mode_append_and_clear_follow_platform(){let mut s=DialerFilterState::default();s.set_mode(DialerMode::DigitsOnly);s.append("12");assert_eq!(s.filter_text(),"12");s.set_mode(DialerMode::LettersOnly);s.append("ab");assert_eq!(s.letters(),"AB");assert_eq!(s.digits(),"");s.clear();assert_eq!(s.mode,DialerMode::DigitsAndLetters);assert_eq!(s.filter_text(),"");}
#[test] fn phone_symbols_are_accepted(){let mut s=DialerFilterState::default();for c in "1#*+N;".chars(){s.type_char(c);}assert_eq!(s.digits(),"1#*+N;");assert_eq!(s.mode,DialerMode::DigitsAndLetters);}
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_dialer_filter.rs"));}
#[test] fn xml_fields_reflect_state(){use bhoo::*;use bhoo::android_xml::{LayoutState,Visibility};let mut state=LayoutState::default();state.dialer_filters.entry("dialer".into()).or_default().type_char('2');let mut ui=Ui::default();let b=Rect{x:0.,y:0.,width:300.,height:108.};ui.frame(Input::default(),b,0.,|f|{fixture::LAYOUT.render(f,b,&mut state);});assert_eq!(state.text["android:primary"],"2");assert_eq!(state.text["android:hint"],"2");state.dialer_filters.get_mut("dialer").unwrap().type_char('A');ui.frame(Input::default(),b,0.,|f|{fixture::LAYOUT.render(f,b,&mut state);});assert_eq!(state.text["android:primary"],"2A");assert_eq!(state.visibility["android:hint"],Visibility::Invisible);}
#[test] fn host_text_replacement_handles_paste_and_deletion(){let mut s=DialerFilterState::default();s.replace_user_text("12ab");assert_eq!(s.letters(),"12AB");assert_eq!(s.mode,DialerMode::DigitsAndLettersNoDigits);s.replace_user_text("12");assert_eq!(s.mode,DialerMode::DigitsAndLetters);assert_eq!(s.digits(),"12");s.set_mode(DialerMode::DigitsOnly);s.replace_user_text("2a#");assert_eq!(s.digits(),"2#");}
#[test] fn xml_filter_exposes_one_host_text_target(){use bhoo::*;use bhoo::android_xml::LayoutState;let(mut ui,mut state)=(Ui::default(),LayoutState::default());let b=Rect{x:0.,y:0.,width:300.,height:108.};ui.frame(Input::default(),b,0.,|f|{fixture::LAYOUT.render(f,b,&mut state);});let fields:Vec<_>=ui.semantics().iter().filter(|node|node.role==Role::TextField).collect();assert_eq!(fields.len(),1);assert_eq!(fields[0].label.as_ref(),"Dialer filter");}
